INSERT INTO `achievement_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `Reward_lang`, `VerifiedBuild`) VALUES
(63325, 'ruRU', 'Получите 5 искр всестороннего любопытства для фолианта омниума.', 'Исследования с фолиантом омниума', 'Награда: симулякр омниума Солнечного Скитальца', 68974),
(62903, 'ruRU', 'Успокойте 5 бурь в Вале.', 'Инопланетная климатология: Вал', 'Награда: возможность приобрести Кита Рыбную Палочку', 68974),
(63343, 'ruRU', 'Забейте гол тренировочным мячом в Луносвете, используя гербовую накидку за участие.', 'Го-о-ол!', 'Награда: заветная сфера Азерота, \"Гордость Орды\" (в рамке), \"Гордость Альянса\" (в рамке)', 68974),
(61336, 'ruRU', 'Почтите огни зон Midnight.', 'Полуночный страж огня', '', 68974),
(61335, 'ruRU', 'Почтите огни зон Midnight.', 'Полуночный хранитель огня', '', 68974),
(61936, 'ruRU', 'Победите слепосветный авангард в Шпиле Бездны в обычном или более сложном режиме так, чтобы на всех игроков действовала \"Мощнейшая аура\".', 'Аура крутости', '', 68974),
(61911, 'ruRU', 'Победите Ваэлгора и Эззорака в Шпиле Бездны в обычном или более сложном режиме после того, как все игроки разобьют связи каждой нуль-зоны в течение 3 секунд.', 'На старт, внимание, кусь!', '', 68974),
(61514, 'ruRU', 'Преклоните /колени всей группой перед павшим королем Салхадааром, а затем победите его в Шпиле Бездны в обычном или более сложном режиме.', 'Это измена', '', 68974),
(61381, 'ruRU', 'Победите Бело\'рена Дитя Ал\'ара, наполнив яйцо Солнечного Колодца магией Света и Бездны, в марше на Кель\'Данас в обычном или более сложном режиме.', 'Раньше точно яйцо', '', 68974),
(61346, 'ruRU', 'Победите Корону космоса в Шпиле Бездны в обычном или более сложном режиме, убив мясное чудовище и вернув все его мясо Пустоте.', 'Мы точно еще встретимся', '', 68974),
(61611, 'ruRU', 'Победите Торжество Полуночи в марше на Кель\'Данас в эпохальном режиме в составе группы гильдии.', 'Эпохальный режим: гильдейский марш к Торжеству Полуночи', '', 68974),
(61380, 'ruRU', 'Заработайте указанные ниже достижения рейдов.', 'Слава рейдеру Midnight', 'Транспорт: сумрачный боронитель', 68974),
(62874, 'ruRU', 'Заработайте перечисленные достижения:', 'Межзвездное путешествие', 'Награда: возможность приобрести нуль-панцирь из кузни Пустоты', 68974);
INSERT INTO `adventure_journal_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `ButtonText_lang`, `RewardDescription_lang`, `ContinueDescription_lang`, `VerifiedBuild`) VALUES
(909, 'ruRU', 'Фолиант омниума: новая информация', 'У магистров появилась новая информация, которая позволит усилить еще больше рун в фолианте омниума.', 'Принять задание', 'Дает в награду искру всестороннего любопытства, которая может усилить другую руну в фолианте омниума.', '', 68974);
INSERT INTO `area_table_locale` (`ID`, `locale`, `AreaName_lang`, `VerifiedBuild`) VALUES
(15966, 'ruRU', 'Логово Предаксаса', 68974);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(4618, 'ruRU', 'Режим отдыха: включен.\nСтепень расслабления: максимальная.\nВнутренняя температура: низкая.', '|cFFFFD200Промоакция|r |n', 68974),
(4617, 'ruRU', 'Основное назначение: героические подвиги.\nПредпочитаемый вид подвигов: захватывающие.\nВторостепенное назначение: становление героем.\nПредпочитаемый вид героя: великий.', '|cFFFFD200Промоакция|r |n', 68974),
(4949, 'ruRU', 'Частица, оставшаяся после попытки Фиракка осквернить Амирдрассил.', '|cFFFFD200Торговец: |rЗидан|n|cFFFFD200Зона: |rВальдраккен|n|cFFFFD200Цена: |r2200|Hcurrency:1166|h|TInterface\\ICONS\\PVECurrency-Justice.blp:0|t|h', 68974),
(5074, 'ruRU', 'В отличие от большинства демонов Бездны из Бури, Тиша предпочитает мир и спокойствие тишины. Даже если придется заткнуть рты болтливым сородичам.', '|cFFFFD200Достижения:|r \"Решающий успех: Вал\" и \"Решающий успех: Найтал\"|n|cFFFFD200Торговец: |rКифаан|n|cFFFFD200Зоны: |rВал или Найтал|n|cFFFFD200Цена: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(5073, 'ruRU', 'Равняясь на взрослых, эта малышка всегда рвется в драку. Она начнет с маленьких пауков и постепенно набьет лапу.', '|cFFFFD200Достижение:|r \"Ультрабойня\"|n|cFFFFD200Торговец: |rКифаан|n|cFFFFD200Зоны: |rВал или Найтал|n|cFFFFD200Цена: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(4898, 'ruRU', 'Замороженная рыба – любимое лакомство Кита. Заморозьте пару рыбешек и обретете друга на всю жизнь.', '|cFFFFD200Достижение:|r \"Инопланетная климатология: Вал\"|n|cFFFFD200Торговец: |rКифаан|n|cFFFFD200Зона: |rНайтал или Вал|n|cFFFFD200Цена: |r50|Hitem:238365|h|TInterface\\ICONS\\INV_Misc_Fish_41.blp:0|t|h |n|n', 68974);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(317639, 'ruRU', 'Командир Тала\'саан скидывает покров световой завесы и шагает вперед.', '', 68974),
(314421, 'ruRU', 'А-А-А!', '', 68974),
(314420, 'ruRU', 'ЗУЛ\'ДЖАН, СТОЙ!', '', 68974),
(314419, 'ruRU', 'НИ ХАШ\'ЭЙ!', '', 68974),
(314418, 'ruRU', 'С такой силой нам не нужны НИ ЛОА!', '', 68974),
(314417, 'ruRU', 'Нет!', '', 68974),
(314416, 'ruRU', 'Брось!', '', 68974),
(314415, 'ruRU', 'Это темная магия!', '', 68974),
(314414, 'ruRU', 'Зул\'джан!', '', 68974),
(314413, 'ruRU', '(возгласы)', '', 68974),
(314412, 'ruRU', 'Тот самый ключ...', '', 68974),
(314411, 'ruRU', 'Нашелся!', '', 68974),
(314410, 'ruRU', 'Ага!', '', 68974),
(314408, 'ruRU', 'она все поймет, не сомневайся.', '', 68974),
(314407, 'ruRU', 'Когда ты завладеешь силой Ула\'тек,', '', 68974),
(314406, 'ruRU', 'Возьми ключ, Зул\'джан.', '', 68974),
(314405, 'ruRU', 'Когда она увидит дядю...', '', 68974),
(314404, 'ruRU', 'Лоа не ослабляют свою хватку...', '', 68974),
(314403, 'ruRU', 'А как же моя сестра?', '', 68974),
(314402, 'ruRU', 'Закончить то, что мы начали с твоим дедом.', '', 68974),
(314401, 'ruRU', 'Избавить от пустых обещаний лоа.', '', 68974),
(314400, 'ruRU', 'Чтобы спасти наш народ.', '', 68974),
(314399, 'ruRU', 'И мне нужна твоя помощь.', '', 68974),
(314398, 'ruRU', 'Малакрасс...', '', 68974),
(314397, 'ruRU', 'Да...', '', 68974),
(314396, 'ruRU', 'Так, значит, ты...', '', 68974),
(314395, 'ruRU', 'Ты знал моего деда?', '', 68974),
(314394, 'ruRU', 'Мы с Зул\'джином пытались изменить ее...', '', 68974),
(314393, 'ruRU', 'Увы, такова судьба нашего народа.', '', 68974),
(314392, 'ruRU', '...и где они были в его последнюю минуту?', '', 68974),
(314391, 'ruRU', 'Всю жизнь он прослужил лоа...', '', 68974),
(314390, 'ruRU', 'Ужасно...', '', 68974),
(314389, 'ruRU', 'Нет-нет-нет, я н-не...', '', 68974),
(314388, 'ruRU', 'Нет...', '', 68974),
(314387, 'ruRU', 'Он умер, Зул\'джан.', '', 68974),
(314386, 'ruRU', 'ДЯДЯ!', '', 68974),
(314385, 'ruRU', 'Дядя!', '', 68974),
(314384, 'ruRU', '(кашель)', '', 68974),
(310355, 'ruRU', 'А я обыщу башню Утренней Звезды и найду деталь. Приходи туда, если сможешь. И, Роммат... удачи.', '', 68974),
(317797, 'ruRU', '<Лицо Тала\'саана каменеет.>\n\nМногие из наших братьев и сестер... пропали в воющем урагане Шпиля Бездны.\n\nМногие другие получили раны, и не только телесные.\n\nЯ знаю, какая участь постигла бойцов в Шпиле, $n. Ты ведь тоже помнишь? Ярость... смятение... отчаяние.\n\nМы потеряли много верных товарищей в этой войне. У меня не хватило духу просить Фарию отрядить больше солдат.', '', 68974),
(317795, 'ruRU', 'Я Тала\'саан, командир озаренных в Армии Света.\n\nПо просьбе Маэллы я приму участие в охоте на слуг Бездны и хал\'хадаров.\n\nС этими врагами нас связывают непростые отношения, но у нас большой опыт путешествий по незнакомым мирам.\n\nВсе участники экспедиции, которых ты здесь видишь, – одни из лучших воинов Армии Света.', '', 68974),
(317659, 'ruRU', '<Рунические буквы мерцают у вас перед глазами и постепенно складываются в слова.>\n\nПанель управления операцией \"Матрица света\": подключена\n\nОбозначение планеты: Найтал\n\nУровень опасности: умеренный. \n \nУсловия окружающей среды: тяжелые. Рекомендуется соблюдать осторожность.\n\nТекущий выявленный риск: ХАЛ\'ХАДАРЫ\n...\n\nЗапрос?', 'Командир Тала\'саан бросает на вас взгляд и одобрительно кивает.', 68974),
(317656, 'ruRU', '', 'Тул\'амар стискивает зубы и на мгновение замолкает. Она быстро зыркает на вас здоровым глазом, а затем снова переводит взгляд на Тала\'саана.', 68974),
(317572, 'ruRU', 'Я буду внимательно следить за моей – точнее, нашей – новой пешкой.', '', 68974),
(317571, 'ruRU', 'Наша работа еще не завершена, но не бойся, что Импот станет нам мешать. Он засядет в Акрополе, опьяненный победой.', '', 68974),
(317109, 'ruRU', 'Эта ледяная дыра того гляди зачахнет. Есть гораздо более подходящие, более удобные миры.', '', 68974),
(317012, 'ruRU', '', 'В этом мире они найдут колонию выживших дренеев, $n.\n\nНашабор так и не сдался Пылающему Легиону, и те, кого не забрал \"Генедар\", продолжают там жить.\n\nХал\'хадары пока об этом не знают, но их нападения на Азерот доказывают, что этих эфириалов не волнуют жизни других.\n\nНарод Нашабора в опасности.\n\nОтнеси этот голографит Тул\'амар. Она должна знать.', 68974),
(317008, 'ruRU', '', 'Телору\'вил тоже считается разрушенным миром, но посмотри, что они здесь нашли.\n\nЕсли в их руках оказалась карта этого и всех прочих миров, где дренеи побывали до Найтала, то хал\'хадары получили большой список целей.\n\nДозорные, устройства, гробницы, разрушенные города – им будет чем поживиться.\n\nА ты знаешь, что они найдут на Нашаборе вместо заброшенных руин?', 68974),
(317007, 'ruRU', '', 'Дозорная, с которой тебе пришлось сразиться в Вилалдоне, была известным звездочетом, когда мы еще жили на Аргусе.\n\nСреди консулов лишь немногие читали по звездам так же точно, как Кирсалия.\n\nСогласно записи на голографите, она отметила на карте путь \"Генедара\", бежавшего от Пылающего Легиона.\n\nТеперь эта карта – напоминание о том, сколько миров покинул \"Генедар\", и о тех, кого пришлось бросить.\n\nПоследний пункт ее схемы перелетов – Найтал. Или Телору\'вил, как они его называют.\n\nТам же упоминается и Нашабор.\n\nКак и все, кто спасался оттуда бегством, она решила, что Нашабор был безвозвратно потерян.', 68974),
(316762, 'ruRU', 'Клинок Бездны Маэлла попросила нас сопроводить экспедицию.\n\nЗнания Вераан о Бездне и деятельности хал\'хадаров делают ее незаменимой для этого задания.\n\nА я... Кто знает? Вдруг им понадобится разобрать и изучить какое-нибудь устройство?', '', 68974),
(316750, 'ruRU', '', 'В архивах Анторуса говорится, что Легион захватил лишь малую часть Вала. Интересно, с чего бы это...\n\nПочти по всей планете бушуют сильнейшие градовые бури, пробивающие корпуса кораблей.\n\nЛегион потерял как минимум два боевых судна в тщетной попытке завоевать этот мир.\n\nСо временем они все же создали здесь несколько опорных пунктов, но это были лишь заставы в разных частях планеты.\n\nНасколько нам известно, служба на них была наказанием за череду провалов.', 68974),
(316562, 'ruRU', '', '<Верховный маг И\'мера поглощена делом: ее руки так и мелькают, вводя в консоль различные рунические символы.>\n\nЭнергия Бездны на юге идет из Акрополя.\n\nСудя по этим показателям, крепость уходит глубоко под лед.', 68974),
(316520, 'ruRU', '', 'Иллидари знают этот ледяной ад лучше, чем кто-либо из нас. Демоны Легиона называли этот мир Вал и использовали его лютый холод, допрашивая пленников.\n\nЭта морозная мертвая пустошь – идеальное место для убежища доманааров.\n\n<Маэлла, почти не таясь, бросает взгляд на Децима.>', 68974),
(316419, 'ruRU', '<На маяке есть две кнопки для выбора цели телепортации: Луносвет или Буря Бездны. Пожалуй, не стоит проверять, что будет, если нажать обе кнопки одновременно.>', '<На маяке есть две кнопки для выбора цели телепортации: Луносвет или Буря Бездны. Пожалуй, не стоит проверять, что будет, если нажать обе кнопки одновременно.>', 68974),
(316274, 'ruRU', '', 'Благодаря найденным голографическим чертежам мы знаем, где эфириалы достали дренейские артефакты.\n\nПод островом есть склеп, который соорудили мои сородичи.\n\nХал\'хадары воруют из него и стражей, и потревоженных духов мертвых.\n\nСудя по их записям, в склепе осталось немало дозорных, но их изучение ни к чему не привело.\n\nЕсли нам повезет, мы сумеем сорвать их эксперименты.\n\nТала\'саан возглавит вылазку в склеп.', 68974),
(316214, 'ruRU', '', '<Верховный маг И\'мера забирает у вас кристалл, вытаращив глаза от удивления.>\n\nЭто дренейские руны, $n. Хотя тут нечему удивляться.\n\nХал\'хадары словно падальщики, когда идет речь о технике. Они слетаются на руины разрушенного мира и обчищают его.\n\nДолжно быть, они обнаружили наши кристальные устройства в одном из таких миров – как и наши экзоскелеты.\n\nЯ осмотрю этот образец. Отнеси остальные Кифаану. Он ведет записи обо всех технологиях хал\'хадаров.\n\nИ мнение техноманта из Консорциума нам вовсе не помешает.', 68974),
(316212, 'ruRU', '', '<Верховный маг И\'мера поглощена делом: ее руки так и мелькают, вводя в консоль различные рунические символы.>\n\nДумаю, мы сумеем выяснить, что замышляют наши враги в Найтале. Нужно лишь немного везения и очень много работы по расшифровке.\n\nВ любом случае нам следует побольше узнать о самих хал\'хадарах.\n\nНе стоит упускать такую возможность.', 68974),
(314754, 'ruRU', 'Позади враги. Обернитесь!', 'Позади враги. Обернитесь!', 68974),
(313932, 'ruRU', '', 'Клинок Бездны Маэлла мрачно смотрит на проекцию Децима.', 68974),
(313749, 'ruRU', '', 'Уже пора? Тебя прислала Маэлла? Мне надо кое с чем разобраться перед уходом!\n\nЯ хочу совместить простое маскирующее заклинание и вот эту связь, чтобы модифицировать технологию световой завесы.\n\nПо моим расчетам, вместе они скроют весь наш лагерь, когда мы высадимся.\n\nНо сначала мне нужен доброволец для эксперимента с невидимостью, чтобы протестировать максимальное расстояние связи.\n\nПоможешь?', 68974),
(310380, 'ruRU', 'Уничтожение доманаарского императора не вызовет того же эффекта, что убийство смертного лидера.', '', 68974),
(310377, 'ruRU', '', 'Пертинакс больше не доставит нам проблем. Все благодаря нашему герою.', 68974),
(310376, 'ruRU', 'А если их \"император\" решит показаться тебе на глаза, окажи мне услугу и разделайся с ним раз и навсегда.', '', 68974),
(310375, 'ruRU', '', 'Ослабив силы Бездны здесь, мы уменьшим давление на союзников в нашем мире. Посей хаос, герой.', 68974),
(310366, 'ruRU', 'Свет... Скверна... Бездна... До чего хрупкий и опасный союз. Просто загляденье.', '', 68974),
(309048, 'ruRU', 'Хал\'хадары установили на своих летающих лодках \"защитные\" турели. Давай-ка посмотрим, чего стоит эта защита.', '', 68974),
(309047, 'ruRU', 'Я почти ничего не знаю об этих \"хал\'хадарах\", но они кажутся куда опаснее Темной Стражи. Советую сократить их число сейчас, чтобы горько не пожалеть потом.', '', 68974),
(309020, 'ruRU', '', 'Наши озаренные разведчики обнаружили следы древнего создания Бездны. Достанешь несколько образцов для исследований?', 68974),
(309018, 'ruRU', 'Ваши... \"смелые\" разведчики решили воспользоваться нестабильными ресурсами этого мира. Постарайся собрать эти ресурсы без досадных происшествий.', '', 68974),
(309015, 'ruRU', '', 'Нарушив работу доманаарской сети порталов, мы прервем вторжение. Сделай все возможное, чтобы замедлить их действия.', 68974),
(309014, 'ruRU', 'Как и следовало ожидать, выполнению твоего задания мешает очередная \"помеха\". Приди, уничтожь, победи.', '', 68974),
(318546, 'ruRU', 'Терраса Магистров открывает двери перед всеми, кто желает учиться.\n\nЭта цитадель знаний – свободный форум идей, где нет места вражде и эгоизму.\n\nНо когда я вижу тех, кто вернулся... Я не могу не чувствовать...\n\n<Магистр сжимает зубы и замолкает.>', 'Терраса Магистров открывает двери перед всеми, кто желает учиться.\n\nЭта цитадель знаний – свободный форум идей, где нет места вражде и эгоизму.\n\nНо когда я вижу тех, кто вернулся... Я не могу не чувствовать...\n\n<Магистр сжимает зубы и замолкает.>', 68974),
(318542, 'ruRU', '<Магистр из высших эльфов вздыхает при виде вас.>\n\nТолько не кричи на меня... Я не выдержу еще одного злого взгляда или упрека.\n\nЯ просто хочу изучать магию и осваивать новые заклинания. Что тут такого?\n\nСсоры меня скоро с ума сведут!', '<Магистр из высших эльфов вздыхает при виде вас.>\n\nТолько не кричи на меня... Я не выдержу еще одного злого взгляда или упрека.\n\nЯ просто хочу изучать магию и осваивать новые заклинания. Что тут такого?\n\nСсоры меня скоро с ума сведут!', 68974),
(317974, 'ruRU', 'Совершенствование и изучение магии – вся суть нашей работы. Нас, магистров.\n\nНадеюсь все-таки, что наши прогрессивные коллеги помогут остальным понять перспективы исследования Бездны.\n\nМы-то не собираемся никуда изгонять тех, кто откажется участвовать.', 'Совершенствование и изучение магии – вся суть нашей работы. Нас, магистров.\n\nНадеюсь все-таки, что наши прогрессивные коллеги помогут остальным понять перспективы исследования Бездны.\n\nМы-то не собираемся никуда изгонять тех, кто откажется участвовать.', 68974),
(317973, 'ruRU', 'Велдарин утверждает, что первые искатели знаний исследовали злобную силу, которую наши предки почувствовали в Тирисфале.\n\nНикто не знает, что они нашли, но немногие вернулись в здравом уме.\n\nОни увидели или обнаружили нечто такое, из-за чего Дат\'ремар сразу запретил магию Бездны.\n\nКак думаешь, Умбрий тоже заглянул в ту тьму? А нам разрешат?', 'Велдарин утверждает, что первые искатели знаний исследовали злобную силу, которую наши предки почувствовали в Тирисфале.\n\nНикто не знает, что они нашли, но немногие вернулись в здравом уме.\n\nОни увидели или обнаружили нечто такое, из-за чего Дат\'ремар сразу запретил магию Бездны.\n\nКак думаешь, Умбрий тоже заглянул в ту тьму? А нам разрешат?', 68974),
(317972, 'ruRU', '<Магистр вздыхает при виде вас.>\n\nТолько не кричи на меня... Я не выдержу еще одного злого взгляда или упрека.\n\nЯ просто хочу изучать магию и осваивать новые заклинания. Что тут такого?\n\nСсоры меня скоро с ума сведут – а я, на минуточку, смотрел прямо в черную дыру!', '<Магистр вздыхает при виде вас.>\n\nТолько не кричи на меня... Я не выдержу еще одного злого взгляда или упрека.\n\nЯ просто хочу изучать магию и осваивать новые заклинания. Что тут такого?\n\nСсоры меня скоро с ума сведут – а я, на минуточку, смотрела прямо в черную дыру!', 68974),
(317917, 'ruRU', 'Честно говоря, он вряд ли собирался это делать.\n\nПредательство совета и нашего народа – отвратительная подлость, но разрушать омниум он не стал бы.\n\nЗачем ему губить архив запретных знаний, который он так долго мечтал получить?\n\nСкорее уж он бы похитил весь омниум.\n\nМожет, потому он и довольствовался его частью.', '', 68974),
(317750, 'ruRU', 'Прекрасный вопрос! С чего бы начать...\n\nВ омниуме, конечно, есть магикула тайной магии. Мудрость высокорожденных, накопленная за тысячи лет, стала основой процветания нашей новой нации на незнакомом континенте.\n\nЕсть магикулы огня и других стихий – природные основы мироздания.\n\nВ магикуле Света содержатся очень любопытные сакральные знания. Верховные луносветские жрецы внесли большой вклад в их сбор.\n\nИ, естественно, всех обычно интересуют запретные магикулы...\n\nБездна. Скверна. Некромантия. Хотя, как мне представляется, теперь некоторые ограничения на них... придется ослабить.\n\n<Велдарин задумчиво морщит лоб.>', '', 68974),
(317749, 'ruRU', 'Советую прочесть табличку как раз у самого омниума. Она исчерпывающе описывает намерения Дат\'Ремара.\n\nНо если коротко, причины у него были многочисленные, амбиции смелые, а цели ясные, как небеса над Вечной Песней.\n\nДат\'Ремар в юности стал свидетелем множества трагедий и знал, что нельзя пренебрегать магическими силами нашего мира.', '', 68974),
(317744, 'ruRU', 'Добро пожаловать в Ликаней!\n\nПеред тобой сосуд безграничных знаний и бесконечного магического потенциала!\n\nЯ имею в виду, естественно, омниум Солнечного Скитальца.\n\nЯ лишь скромный смотритель, приставленный отвечать юным магистрам и наставлять их на пути к свершениям магической науки.\n\nЕсли хочешь что-то спросить, я с радостью помогу.', '', 68974),
(317738, 'ruRU', 'Почему они называются магикулами? Почему не манакулами? Хотя нет, так похоже на монокли.\n\nОмникулы? Или омни... кули?\n\nДат\'Ремар меня побери, я все это время произносил неправильно?', 'Почему они называются магикулами? Почему не манакулами? Хотя нет, так похоже на монокли.\n\nОмникулы? Или омни... кули?\n\nДат\'Ремар меня побери, я все это время произносила неправильно?', 68974),
(317722, 'ruRU', '<На мгновение Роммат нахмуривается.>\n\nУмбрий и его... последователи подчиняются тем же правилам в обращении с омниумом.\n\nЯ не желаю даже слышать про \"исключения\" для рен\'дорай – никакого мне тут зоопарка с жутчайшими тварями Бездны.\n\nКак ты понимаешь, сфера изысканий Умбрия вызывает у меня ноль доверия... Но ему лично я верю. С оговорками.\n\nБлагодаря контролю над Бездной, которого якобы добились его ученики, мы сможем... более обстоятельно подойти к обсуждению магикулы Бездны.\n\nНо в стандартную программу магия Бездны войдет только через мой труп!', '', 68974),
(317721, 'ruRU', 'Только магистрам разрешается прикасаться к знаниям омниума, да и то не без ограничений.\n\nСам Дат\'Ремар установил правила и положения много поколений назад.\n\nСледуя этим правилам, мы не только открывали и документировали новые опасные магические реакции, но и защищали себя от этих нестабильных сил.\n\nХотя когда-то доступ к магикуле Скверны был строго запрещен.\n\nКак же меняются времена...', '', 68974),
(317719, 'ruRU', '<Умбрий улыбается и оглядывается на Роммата.>\n\nКонечно, Роммат... сильно не одобряет мои исследования, но омниум всегда охраняли строгие ограничения и правила.\n\nОмниум – не банальная энциклопедия, чтобы открывать его для широкой магической публики. В чем нам очень повезло.\n\nСтрашно подумать, что еще бы натворил Дар\'Кхан, будь у него полный доступ.\n\nМеры защиты действуют со времен Дат\'Ремара.\n\nОн рано познакомился с Бездной, а в Войне Древних своими глазами видел разрушения из-за силы Скверны – потому-то на эти разновидности магии наложили табу.\n\nНо все-таки я не сторонник тотальных запретов.', '', 68974),
(317717, 'ruRU', 'Мы все задавались этим вопросом с тех пор, как омниум погрузился в тишину.\n\nНикто точно не знает, что произошло. Мы знаем состояние, в котором омниум нашли, и ничего больше.\n\nМеня здесь не было, когда терраса пала... Когда пришел Дар\'Кхан... Но я видел последствия.\n\nОмниум совершенно опустел. Ни единого проблеска энергии, ни одной магикулы.\n\nЛишь безжизненный магический каркас. Просто мурашки по коже... мягко говоря.', '', 68974),
(317715, 'ruRU', 'В свое время мы нашли лишь пустой каркас среди обломков. Никаких магикул. Никакого свечения рун.\n\nЕсли не считать остаточной энергии после бойни Дар\'Кхана, он не подавал признаков жизни.\n\nМагикулы изначально создавались как неотделимая часть омниума. Мы даже не представляли, что они могут исчезнуть.\n\nКогда реликвия пробудилась и магикулы вернулись в нее, мы заметили пустоту в центральной матрице.\n\nС такой аномалией мы не сталкивались никогда раньше.\n\nМагикула, которую прочли последней, просто пропала или разрушилась. А в нашем случае ее украли.', '', 68974),
(317714, 'ruRU', 'Поначалу да.\n\nМы знали, что он устроил резню во время собрания на террасе. Доказательства забрызгали все стены и сам омниум.\n\nНо когда мы обыскали кабинет и дом, то лишь убедились в его приверженности к темнейшим школам магии.\n\nКак потом заметил Умбрий, Дратир жаждал силы и знаний, а поврежденный омниум не отвечал его... интересам.', '', 68974),
(317713, 'ruRU', 'У меня... нет ответа.\n\nНо мы пытались оживить омниум всеми средствами. Даже ключ-шифр Солнечного Скитальца на него не подействовал.\n\nКель\'тас в то время... горевал.\n\nКак и все мы, он так много потерял в одночасье.\n\nВ отчаянии он искал спасительные ответы. Ради всего нашего народа.\n\nЗнания из омниума могли бы помочь нам... И даже наставить принца на истинный путь.\n\nНо когда омниум не ответил, мы оказались в тупике.', '', 68974),
(316792, 'ruRU', 'Ключ Солнечного Скитальца не распознан. Зеркальный отголосок активирован.', 'Ключ Солнечного Скитальца не распознан. Зеркальный отголосок активирован.', 68974),
(315312, 'ruRU', 'Это Башня Утренней Звезды. Здесь Дар\'Кхан Дратир провел свое детство. Когда-то это было спокойное и приятное место.\n\nПосле моего изгнания из Луносвета я разыскал часть исследований Дар\'Кхана о Бездне, которые и привели меня сюда.\n\nСудя по всему, он занимался своими изысканиями тайно. На вершине этой башни я впервые открыл разлом в Телогрус.\n\nЯ не знал, что здесь есть секреты, о которых мы даже не подозревали...', '', 68974),
(314998, 'ruRU', 'Раньше мы выбирали искателей только из магистров, но твои особые навыки подходят... нашему профилю.\n\nТвоя роль – проводить исследования, которые будем поручать мы с Умбрием.\n\nЗа успешное выполнение задач мы будем снабжать тебя мощными руническими усилениями.\n\nВсе руны собраны в фолианте омниума. Тебе решать, какие из них усиливать.\n\nВопросы?', '', 68974),
(314900, 'ruRU', '<Роммат пристально смотрит на безмолвный омниум.>\n\nМы почти у цели. Теперь, когда ключ-шифр Бело\'вира у нас, а вы с Умбрием вернули недостающую магикулу Бездны, остается лишь одно.\n\nТеперь или никогда, $n. Приступим?', '', 68974),
(314899, 'ruRU', 'Я изучал омниум на протяжении многих лет. Как и все магистры до меня, я постиг все, что он мог дать – руны, заклинания, чары...\n\nДень, когда он умолк, был нашим черным днем по многим причинам. Я и не надеялся, что он снова оживет. Даже удивительно, как далеко мы смогли зайти.', '', 68974),
(314791, 'ruRU', 'Бело\'вир, судя по всему, оставил инструкции, как попасть в его хранилище... инструкции, которые долго дожидались меня.\n\nЗная своего предшественника, могу предположить, что он воспользовался заклинанием зеркальных копий, которым владел в совершенстве.\n\nНам с тобой придется пройти это испытание вместе. Я отправлюсь наверх в свой кабинет и попробую снять самые сложные из оберегов.\n\nТы сможешь помочь моим зеркальным копиям рассеять три оберега на внешних ярусах?', '', 68974),
(314746, 'ruRU', 'Я все гадаю, как долго Дар\'Кхан вынашивал идею захватить магикулу Бездны и ее запретные тайны.\n\nКогда мы только стали магистрами, нам сразу пояснили, какие школы магии и связанные с ними магикулы строго запрещены в нашем круге.\n\nДар\'Кхан проявлял интерес к силам Бездны уже когда мы учились в Даларане, поэтому я знал, что у него как минимум есть к этому склонность.\n\nНеужели он хотел похитить магикулу с того самого дня, как мы впервые ступили в Ликаней?\n\nИли же он сделал это во внезапном порыве, когда убивал собратьев на террасе?', '', 68974),
(314744, 'ruRU', 'Когда-то мне казалось, что я постиг все тайны, сокрытые Дар\'Кханом в этом месте. Сегодняшние события... определенно стали неожиданностью.\n\nИз предосторожности – и поскольку Роммат непременно спросит об этом – я должен удостовериться в том, что здесь больше ничего не скрыто.\n\nПосле нашего ритуала я тут все уберу и буду ждать тебя на террасе Магистров. Приходи туда, как только поможешь Роммату восстановить ключ-шифр Бело\'вира.', '', 68974),
(314678, 'ruRU', 'Мои подозрения подтвердились... Ты чувствуешь это в воздухе, $n? Холодную отдаленную пульсацию, словно приглушенное сердцебиение.\n\nМне кажется, это и есть тот спрятанный от нашего взор компонент, что мы ищем.\n\nПодходящее заклинание и сосредоточение заставят Бездну открыть нам секреты Дар\'Кхана, которые до сих пор здесь таятся.\n\nПока ты соединяешь якоря друг с другом, я смогу сотворить это заклинание.\n\nБудь начеку... Бездна уже взывает к нам, подгоняя к цели.', '', 68974),
(310354, 'ruRU', 'Надо будет снять защитные чары. Подожду нашего героя на месте.', '', 68974),
(310059, 'ruRU', 'Тайная магия, Скверна или даже Свет и... Бездна – Дат\'Ремар создал омниум, чтобы собирать знания обо всех этих силах.', '', 68974),
(317919, 'ruRU', 'Как и многие другие.\n\nОбычно я перенаправляю все вопросы к нашему недопенсионеру – хранителю знаний Велдарину.\n\nНо в благодарность за возвращение омниума я утолю твое любопытство.', '', 68974),
(317573, 'ruRU', 'Весь потенциал... этого мира... теперь мой.', '', 68974),
(309931, 'ruRU', 'Следопыты, соберитесь! Покажем этим чудовищам, почему именно нас избрали защищать анклав!', 'Следопыты, соберитесь! Покажем этим чудовищам, почему именно нас избрали защищать анклав!', 68974),
(307084, 'ruRU', 'О, $n! \n\nХоть кто-то, кто не смотрит на меня с неприкрытой ненавистью. Они меня пока терпят в своем городе, но попомни мои слова – Роммат при первой же возможности использует свои невидимые чародейские стрелы.\n\nОн в свое время объединил \"Скачок\" и \"Чародейские стрелы\", чем отбил охоту у многих желающих вызвать его на магический поединок.\n\nОн не любит это признавать, но это именно я подкинул ему идею, как сделать чародейские стрелы невидимыми, чтобы застать соперника врасплох.\n\nНу, в любом случае Лор\'темар дал мне разрешение здесь находиться, и мне доставляет немалое удовольствие наблюдать, сколько дискомфорта всем остальным доставляет одно мое присутствие.', '', 68974),
(306595, 'ruRU', 'Нам... надо сообщить Лор\'темару, что произошло. Иди вперед.', '', 68974),
(304405, 'ruRU', 'Во времена войн и раздора наши сторожевые древа всегда были могучей силой на полях сражений.\n\nВот только поднять их на битву не так-то просто.\n\nЯ отправлю с тобой боевых хранителей старейшины Изумрудная Кора. Ищите любые крупные камни и булыжники, которыми старейшина мог бы кидаться в наших врагов.\n\nОн не пробудится, пока у него не будет метательных камней.', 'Во времена войн и раздора наши сторожевые древа всегда были могучей силой на полях сражений.\n\nВот только поднять их на битву не так-то просто.\n\nЯ отправлю с тобой боевых хранителей старейшины Изумрудная Кора. Ищите любые крупные камни и булыжники, которыми старейшина мог бы кидаться в наших врагов.\n\nОн не пробудится, пока у него не будет метательных камней.', 68974),
(303273, 'ruRU', '', 'Сторожевые древа – могучие осадные орудия, которые запросто могут выкашивать задние ряды неприятеля.\n\nОрда очень хорошо знакома с их разрушительной мощью.', 68974),
(300503, 'ruRU', '', 'Нет, этого не может быть. Я отправила его Улену, замещающему меня сенешалю, с помощью магии. Что-то произошло в Сурамаре.', 68974),
(292933, 'ruRU', 'У тебя... ушло немало сил, и ты это заслуживаешь.', '', 68974),
