INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3033, 'ruRU', 'Измученный проглот', '|cFFFFD200Зоны:|r Вал и Найтал |n|cFFFFD200Достижение:|r \"Героические решающие сражения\"|n|cFFFFD200Торговец:|r Кифаан|n|cFFFFD200Цена: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'И доманаары, и эфириалы пытались посадить этого пожирателя в клетку, но каждый раз терпели неудачу. Теперь наполненный энергией Бездны измученный проглот готов сеять хаос.', 68974),
(2990, 'ruRU', 'Нуль-панцирь из кузни Пустоты', '|cFFFFD200Достижение:|r \"Межзвездное путешествие\"|n|cFFFFD200Зона:|r Найтал|n|cFFFFD200Торговец:|r Кифаан|n|cFFFFD200Цена: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Этот экзоскелет был создан озаренными, разбит хал\'хадарами и восстановлен техномантом. Внутри него кружит матрица, сплетенная из светлой магии, тайной магии и магии Бездны.', 68974),
(2988, 'ruRU', 'Рассекатель звезд заклинателя Бездны', '|cFFFFD200Достижение:|r \"Кругозвездное путешествие\"|n|cFFFFD200Зона:|r Вал|n|cFFFFD200Торговец:|r Кифаан|n|cFFFFD200Цена: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Вершина достижений заклинателей Бездны – когда-то этот транспорт был символом статуса и власти среди высокопоставленных доманааров. Но когда его создатель таинственным образом исчез, использовать его в ключевых мирах стало дурным тоном.', 68974),
(2975, 'ruRU', 'ИКС-ключительная ракета фейерверка Трюмных Вод', '|cFFFFD200Торговая лавка|r', 'Инженеры Нижней Шахты так увлеклись созданием более скоростной ракеты, что даже не задумались, а СТОИТ ЛИ ее создавать.', 68974);
